class ExecutionGuard:
    """Independent, hard-coded limits enforced outside the model's own
    action space, checked immediately before any order is placed."""

    def __init__(self, max_position_lots=3, max_daily_loss=-5000.0):
        self.max_position_lots = max_position_lots
        self.max_daily_loss = max_daily_loss
        self.daily_pnl = 0.0
        self.trading_halted = False

    def check_and_clip_position(self, proposed_position):
        if self.trading_halted:
            return 0.0  # force flat; no new positions while halted
        return float(np.clip(proposed_position, -self.max_position_lots, self.max_position_lots))

    def record_pnl(self, pnl_change):
        self.daily_pnl += pnl_change
        if self.daily_pnl <= self.max_daily_loss:
            self.trading_halted = True

    def reset_for_new_day(self):
        self.daily_pnl = 0.0
        self.trading_halted = False
